const std = @import("std");

const Node = struct {
    value: i32,
    prev: ?*Node,
    next: ?*Node,
};

pub fn main() !void {
    var n3 = Node{ .value = 30, .prev = undefined, .next = null };
    var n2 = Node{ .value = 20, .prev = undefined, .next = &n3 };
    var n1 = Node{ .value = 10, .prev = null, .next = &n2 };
    n2.prev = &n1;
    n3.prev = &n2;

    std.debug.print("Forward: ", .{});
    var cur: ?*Node = &n1;
    while (cur) |node| {
        std.debug.print("{} ", .{node.value});
        cur = node.next;
    }
    std.debug.print("\n", .{});

    std.debug.print("Backward: ", .{});
    cur = &n3;
    while (cur) |node| {
        std.debug.print("{} ", .{node.value});
        cur = node.prev;
    }
    std.debug.print("\n", .{});
}

